#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# worktree-reclaim.sh: backfill the symlinkDirectories layout onto worktrees
# that already exist.
#
# Usage:
#   bin/worktree-reclaim.sh --dry-run   # show what would change (default)
#   bin/worktree-reclaim.sh --apply     # do it
#
# Claude Code applies worktree.symlinkDirectories only at worktree CREATION
# time. Worktrees created before the config existed keep their own full copy of
# every node_modules tree. This script brings them into the same shape:
# each configured directory becomes a symlink into the main repository.
#
# Read bin/worktree-config.sh first. The same trade-off applies and is the
# whole point: after this runs, worktrees are no longer dependency-isolated.
# `npm install` inside a worktree is safe: it replaces the link with a real
# directory and leaves the shared tree alone, so just re-run this script to
# get the saving back. `npm ci` is NOT safe: it clears node_modules through
# the symlink and empties the MAIN repository's tree, breaking every other
# worktree at once. The pretool/bash/npm-ci-symlink-guard hook (inside
# sync-bash-dispatcher) denies that case.
#
# Guards:
#   - refuses to touch a worktree whose node_modules was modified in the last
#     30 minutes (probable in-flight install in another session)
#   - never removes a directory unless the corresponding source exists in the
#     main repository
#   - skips paths that are already symlinks

set -euo pipefail

MODE="dry-run"
STALE_MINUTES=30

while [[ $# -gt 0 ]]; do
    case "$1" in
        --apply)   MODE="apply"; shift ;;
        --dry-run) MODE="dry-run"; shift ;;
        -h|--help) sed -n '2,25p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *) echo "Unknown option: $1" >&2; exit 1 ;;
    esac
done

if ! git rev-parse --show-toplevel > /dev/null; then
    echo "Error: not in a git repository" >&2
    exit 1
fi
# The main worktree, not whichever worktree we happen to be standing in. This
# is the SYMLINK SOURCE: the one checkout that holds the real installed trees.
WORKTREES=()
in_stanza=0
while IFS= read -r -d '' record; do
    if [[ -z "$record" ]]; then
        in_stanza=0
        continue
    fi
    if [[ "$in_stanza" -eq 0 && "$record" == worktree\ * ]]; then
        WORKTREES+=("${record#worktree }")
        in_stanza=1
    fi
done < <(git worktree list --porcelain -z)

if [[ ${#WORKTREES[@]} -eq 0 ]]; then
    echo "Error: git worktree list returned no worktrees" >&2
    exit 1
fi
MAIN="${WORKTREES[0]}"

# Resolve the canonical-list script next to THIS file, not under $MAIN. The two
# ship together, but the main worktree is routinely parked on a branch that
# predates them, and then "$MAIN/bin/worktree-config.sh" does not exist.
#
# That is not hypothetical: it is how this bug was found. `mapfile < <(cmd)`
# does not abort under `set -e` when cmd fails, so DIRS came back empty, every
# loop body was skipped, and the script printed "links: 0 ... reclaims: 0 MB"
# and exited 0. A no-op that reads as success is worse than a crash.
SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_SCRIPT="$SELF_DIR/worktree-config.sh"

if [[ ! -x "$CONFIG_SCRIPT" ]]; then
    echo "Error: cannot find the canonical list at $CONFIG_SCRIPT" >&2
    exit 1
fi

DIR_LIST=$("$CONFIG_SCRIPT" --list)
DIRS=()
while IFS= read -r dir; do
    if [[ -n "$dir" ]]; then
        DIRS+=("$dir")
    fi
done <<< "$DIR_LIST"

if [[ -z "$DIR_LIST" ]]; then
    echo "Error: $CONFIG_SCRIPT --list returned nothing; refusing to no-op." >&2
    exit 1
fi

echo "main repository: $MAIN"
echo "mode:            $MODE"
echo "directories:     ${#DIRS[@]}"
echo

total_freed=0
linked=0
skipped=0

for wt in "${WORKTREES[@]}"; do
    [[ "$wt" == "$MAIN" ]] && continue
    name=$(basename "$wt")

    # In-flight install guard.
    recent=""
    if IFS= read -r -d '' recent < <(find "$wt" -maxdepth 4 -name node_modules -type d \
        -not -path "*/node_modules/*" -mmin "-$STALE_MINUTES" -print0 -quit); then
        printf '%-26s SKIP  node_modules touched < %s min ago (%s)\n' \
            "$name" "$STALE_MINUTES" "$(basename "$(dirname "$recent")")"
        skipped=$((skipped + 1))
        continue
    fi

    for d in "${DIRS[@]}"; do
        src="$MAIN/$d"
        dst="$wt/$d"

        [[ -e "$src" ]] || continue               # nothing to point at
        [[ -d "${dst%/*}" ]] || continue          # workspace root absent on this branch
        [[ -L "$dst" ]] && continue                # already linked

        if [[ -d "$dst" ]]; then
            bytes=$(du -sk "$dst" | awk 'NR==1 {print $1}')
            total_freed=$((total_freed + bytes))
            printf '%-26s LINK  %-32s reclaims %6s MB\n' "$name" "$d" "$((bytes / 1024))"
            if [[ "$MODE" == "apply" ]]; then
                rm -rf "$dst"
                ln -s "$src" "$dst"
            fi
            linked=$((linked + 1))
        else
            printf '%-26s ADD   %-32s (was missing)\n' "$name" "$d"
            if [[ "$MODE" == "apply" ]]; then
                ln -s "$src" "$dst"
            fi
            linked=$((linked + 1))
        fi
    done
done

echo
echo "links:    $linked"
echo "skipped:  $skipped worktree(s)"
echo "reclaims: $((total_freed / 1024)) MB"
[[ "$MODE" == "dry-run" ]] && echo "(dry run - nothing changed; re-run with --apply)"
exit 0
